def criar_tabelas_legadas(apps, schema_editor):
    with schema_editor.connection.cursor() as cursor:
        cursor.execute("""
            CREATE TABLE IF NOT EXISTS empresas (
                id INTEGER PRIMARY KEY,
                nome TEXT NOT NULL,
                endereco TEXT,
                telefone TEXT,
                site TEXT,
                avaliacao REAL CHECK (avaliacao BETWEEN 0 AND 5),
                maps_id TEXT NOT NULL UNIQUE,
                chave TEXT UNIQUE
            )
        """)
        cursor.execute("""
            CREATE TABLE IF NOT EXISTS envios_whatsapp (
                id INTEGER PRIMARY KEY,
                empresa_id INTEGER NOT NULL,
                session_id TEXT NOT NULL,
                telefone TEXT NOT NULL,
                mensagem TEXT NOT NULL,
                mensagem_hash TEXT NOT NULL,
                status TEXT NOT NULL,
                message_id TEXT,
                erro TEXT,
                criado_em TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
                atualizado_em TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
                UNIQUE (session_id, telefone, mensagem_hash)
            )
        """)
    validar_legado(apps, schema_editor)


def criar_regras_iniciais(apps, schema_editor):
    Tag = apps.get_model('painel', 'Tag')
    RegraTag = apps.get_model('painel', 'RegraTag')
    defaults = (
        ('retífica', 'Mecânica', 'Retífica', 10),
        ('oficina mecânica', 'Mecânica', 'Oficina mecânica', 20),
        ('cafeteria', 'Alimentação', 'Cafeteria', 10),
    )
    for termo, ramo, categoria, prioridade in defaults:
        ramo_tag, _ = Tag.objects.using(schema_editor.connection.alias).get_or_create(nome=ramo, tipo='ramo')
        categoria_tag, _ = Tag.objects.using(schema_editor.connection.alias).get_or_create(nome=categoria, tipo='categoria')
        regra, _ = RegraTag.objects.using(schema_editor.connection.alias).get_or_create(
            termo=termo, defaults={'prioridade': prioridade}
        )
        regra.tags.add(ramo_tag, categoria_tag)


